DATE_LONG='Oct. 16, 2026'; DATE_NOTE='October 16, 2026'
def sub1(p,r,t,label):
    ntext,n=re.subn(p,r,t,count=1)
    if n!=1: raise RuntimeError(f'{label}: expected 1 replacement, got {n}')
    return ntext
for folder,d in DATA.items():
    path=pathlib.Path(folder)/'index.html'; text=path.read_text(encoding='utf-8')
    text=re.sub(r'Updated (?:Sept\.|Oct\.) \d{1,2}, 2026',f'Updated {DATE_LONG}',text)
    text=re.sub(r'Snapshot · (?:Sept\.|Oct\.) \d{1,2}, 2026',f'Snapshot · {DATE_LONG}',text)
    text=sub1(r'(<span data-hit="PA">)\d+(</span>)',rf'\g<1>{d["PA"]}\g<2>',text,f'{folder} PA')
    for key in ['DECISION','HHB','AVG','OBP','K%']:
        text=sub1(rf'(<strong data-hit="{re.escape(key)}">)[^<]*(</strong>)',rf'\g<1>{d[key]}\g<2>',text,f'{folder} {key}')
    text=sub1(r'(<strong data-hit="ABA"><span style="font-size:\.7em">)1P [^<]+<br>2K [^<]+(</span></strong>)',rf'\g<1>1P {d["ABA1"]}<br>2K {d["ABA2"]}\g<2>',text,f'{folder} ABA tile')
    text=re.sub(r'aria-label="ABA: first pitch [^"]+\. Open details"',f'aria-label="ABA: first pitch {d["ABA1"].replace("%"," percent")}, two-strike {d["ABA2"].replace("%"," percent")}. Open details"',text,count=1)
    c=d['decision_counts']
    text=sub1(r'(<b data-popup-value="decision">)[^<]+(</b><span>)\d+( scored decisions</span>)',rf'\g<1>{d["DECISION"]}\g<2>{d["decision_attempts"]}\g<3>',text,f'{folder} decision summary')
    text=sub1(r"\[\['Good',\d+\],\['Minor Poor',\d+\],\['Poor',\d+\],\['Not Scored',\d+\]\]",str([['Good',c['GOOD']],['Minor Poor',c['MINOR']],['Poor',c['POOR']],['Not Scored',c['NOT_SCORED']]]).replace(' ',''),text,f'{folder} decision breakdown')
    af=d['aba_first_counts']; at=d['aba_two_counts']
    text=sub1(r'(<div class="pc-aba-summary"><div><b>)[^<]+(</b><span>1ST PITCH APPROACH</span></div><div><b>)[^<]+(</b><span>2-STRIKE APPROACH</span></div></div>)',rf'\g<1>{d["ABA1"]}\g<2>{d["ABA2"]}\g<3>',text,f'{folder} ABA summary')
    arr1=str([['GOOD',af['GOOD']],['MINOR',af['MINOR']],['POOR',af['POOR']]]).replace(' ',''); arr2=str([['GOOD',at['GOOD']],['MINOR',at['MINOR']],['POOR',at['POOR']]]).replace(' ','')
    matches=list(re.finditer(r"\[\['GOOD',\d+\],\['MINOR',\d+\],\['POOR',\d+\]\]",text))
    if len(matches)<2: raise RuntimeError(f'{folder} ABA breakdown arrays missing')
    m=matches[1]; text=text[:m.start()]+arr2+text[m.end():]; m=matches[0]; text=text[:m.start()]+arr1+text[m.end():]
    text=sub1(r'1P: \d+ scored first pitches · 2K: \d+ plate appearances that reached two strikes\.',f'1P: {d["aba_first_n"]} scored first pitches · 2K: {d["aba_two_n"]} plate appearances that reached two strikes.',text,f'{folder} ABA counts')
    text=re.sub(r'(Good = full credit · Minor = half credit · Poor = zero\. )(?:September|October) \d{1,2}, 2026 HotB backup\.',rf'\g<1>{DATE_NOTE} HotB backup.',text,count=1)
    vals=[d['HHB'],d['WEAK'],d['AVG_HHB'],d['AVG_WEAK']]; rep="['"+"','".join(vals)+"']"
    text=sub1(r"\['[^']*','[^']*','[^']*','[^']*'\]\[i\]",rep+'[i]',text,f'{folder} HHB popup')
    text=re.sub(r"Calculated from this player’s saved HotB game data for the selected Evaluation date range\. Detailed values will appear when HotB publishing is connected\.",f'{d["tracked"]} tracked balls in play · {d["player"]} · {DATE_NOTE} HotB backup.',text,count=1)
    if d.get('pitch'):
        for key,val in d['pitch'].items():
            new,n=re.subn(rf'(<strong data-pitch="{re.escape(key)}">)[^<]*(</strong>)',rf'\g<1>{val}\g<2>',text,count=1)
            if n: text=new
    path.write_text(text,encoding='utf-8')
    print('updated',path)
